//! `cargo xtask tokens`: generate palette, type/metric scale, the GPUI Kit theme and the
//! organism-side constants from `design-system/tokens.json`.
//!
//! - `tokens`: write every generated file.
//! - `tokens --check`: fail when a generated file is stale or the token schema is invalid.
//! - `tokens --contrast`: print WCAG contrast of the text pairs; fail below 4.5:1.

use std::fmt::Write as _;
use std::path::{Path, PathBuf};

use anyhow::{Context, Result, anyhow, bail};
use serde_json::{Map, Value};

pub const TOKENS: &str = "design-system/tokens.json";
const PALETTE: &str = "crates/app/src/ui/theme/palette.rs";
const SCALE: &str = "crates/app/src/ui/theme/scale.rs";
const KIT_THEME: &str = "crates/app/assets/themes/pando.json";

pub const HEADER_RS: &str =
    "// GENERATED by `cargo xtask tokens` from design-system/tokens.json. Do not edit.\n";

/// A generated file: repo-relative path and its generator.
type Generator = fn(&Value) -> Result<String>;
const OUTPUTS: &[(&str, Generator)] = &[
    (PALETTE, generate_palette),
    (SCALE, generate_scale),
    (KIT_THEME, generate_kit_theme),
];

pub fn run(args: &[String]) -> Result<bool> {
    let root = repo_root()?;
    let tokens = read_tokens(&root)?;
    match args.first().map(String::as_str) {
        None => {
            for (path, generator) in OUTPUTS {
                let target = root.join(path);
                std::fs::write(&target, generator(&tokens)?)
                    .with_context(|| format!("writing {}", target.display()))?;
                println!("wrote {path}");
            }
            Ok(true)
        }
        Some("--check") => check(&root, &tokens),
        Some("--contrast") => contrast(&tokens),
        Some(other) => bail!("unknown `tokens` option `{other}` (use --check or --contrast)"),
    }
}

/// True when every generated file matches what the generators produce now.
pub fn check(root: &Path, tokens: &Value) -> Result<bool> {
    let mut ok = true;
    for (path, generator) in OUTPUTS {
        let want = generator(tokens)?;
        let have = std::fs::read_to_string(root.join(path)).unwrap_or_default();
        if have == want {
            println!("{path} is up to date");
        } else {
            eprintln!("{path} is stale: run `cargo xtask tokens` and commit the result");
            ok = false;
        }
    }
    Ok(ok)
}

pub fn repo_root() -> Result<PathBuf> {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .map(Path::to_path_buf)
        .ok_or_else(|| anyhow!("xtask manifest has no parent directory"))
}

pub fn read_tokens(root: &Path) -> Result<Value> {
    let path = root.join(TOKENS);
    let text =
        std::fs::read_to_string(&path).with_context(|| format!("reading {}", path.display()))?;
    serde_json::from_str(&text).with_context(|| format!("parsing {}", path.display()))
}

pub fn object<'a>(v: &'a Value, name: &str) -> Result<&'a Map<String, Value>> {
    v.get(name)
        .and_then(Value::as_object)
        .ok_or_else(|| anyhow!("tokens.json has no `{name}` object"))
}

/// `bosqueDeep` -> `bosque_deep`, `cellSpringKNewborn` -> `cell_spring_k_newborn`.
pub fn snake(name: &str) -> String {
    let mut out = String::new();
    for (i, c) in name.chars().enumerate() {
        if i > 0 && c.is_ascii_uppercase() {
            out.push('_');
        }
        out.push(c.to_ascii_lowercase());
    }
    out
}

pub fn screaming(name: &str) -> String {
    snake(name).to_ascii_uppercase()
}

/// Rust float literal (`34.0`, `0.62`).
pub fn float(v: f64) -> String {
    if v.fract() == 0.0 {
        format!("{v:.1}")
    } else {
        format!("{v}")
    }
}

pub fn num(v: &Value, what: &str) -> Result<f64> {
    v.as_f64().ok_or_else(|| anyhow!("{what} is not a number"))
}

/// `#RRGGBB` of a named colour token, upper-case without the `#`.
pub fn hex_of(tokens: &Value, name: &str) -> Result<String> {
    let hex = object(tokens, "color")?
        .get(name)
        .and_then(|t| t.get("value"))
        .and_then(Value::as_str)
        .ok_or_else(|| anyhow!("colour token `{name}` has no string value"))?
        .trim_start_matches('#')
        .to_ascii_uppercase();
    if hex.len() == 6 && hex.chars().all(|c| c.is_ascii_hexdigit()) {
        Ok(hex)
    } else {
        bail!("colour token `{name}` is not #RRGGBB: {hex}")
    }
}

/// Names of the plain colour tokens (everything but the `marfilAlpha` ramp).
fn color_names(tokens: &Value) -> Result<Vec<&String>> {
    Ok(object(tokens, "color")?
        .keys()
        .filter(|k| k.as_str() != "marfilAlpha")
        .collect())
}

/// Alpha steps of the Marfil ramp as `(step, alpha 0-255)`, e.g. `("62", 158)`.
pub fn marfil_alphas(tokens: &Value) -> Result<Vec<(String, u8)>> {
    let ramp = object(tokens, "color")?
        .get("marfilAlpha")
        .and_then(Value::as_object)
        .ok_or_else(|| anyhow!("tokens.json has no `color.marfilAlpha`"))?;
    let marfil = hex_of(tokens, "marfil")?;
    let mut out = Vec::new();
    for (step, v) in ramp {
        let Some(s) = v.as_str().filter(|s| s.starts_with("rgba(")) else {
            continue; // `note`
        };
        let parts: Vec<&str> = s
            .trim_start_matches("rgba(")
            .trim_end_matches(')')
            .split(',')
            .map(str::trim)
            .collect();
        let [r, g, b, a] = parts[..] else {
            bail!("marfilAlpha.{step}: expected rgba(r,g,b,a), got `{s}`");
        };
        let rgb = format!(
            "{:02X}{:02X}{:02X}",
            r.parse::<u8>()?,
            g.parse::<u8>()?,
            b.parse::<u8>()?
        );
        if rgb != marfil {
            bail!("marfilAlpha.{step} is not Marfil ({rgb} != {marfil})");
        }
        let alpha: f64 = a.parse()?;
        if !(0.0..=1.0).contains(&alpha) {
            bail!("marfilAlpha.{step}: alpha out of range");
        }
        out.push((step.clone(), (alpha * 255.0).round() as u8));
    }
    if out.is_empty() {
        bail!("color.marfilAlpha has no rgba entries");
    }
    Ok(out)
}

fn generate_palette(tokens: &Value) -> Result<String> {
    let names = color_names(tokens)?;
    let alphas = marfil_alphas(tokens)?;
    let mut rs = String::from(HEADER_RS);
    rs.push_str(
        "//! Brand palette. Colours are `0xRRGGBB`; Marfil alpha steps are `Rgba` (alpha 0-255).\n\n",
    );
    rs.push_str("/// A colour with alpha: `rgb` is `0xRRGGBB`, `a` is 0-255.\n#[derive(Clone, Copy, Debug, PartialEq, Eq)]\npub struct Rgba {\n    pub rgb: u32,\n    pub a: u8,\n}\n\nimpl Rgba {\n    /// `0xRRGGBBAA`.\n    pub const fn as_u32(self) -> u32 {\n        (self.rgb << 8) | self.a as u32\n    }\n}\n\n");
    let colors = object(tokens, "color")?;
    for n in &names {
        let role = colors[*n].get("role").and_then(Value::as_str).unwrap_or("");
        writeln!(rs, "/// {role}")?;
        writeln!(
            rs,
            "pub const {}: u32 = 0x{};",
            screaming(n),
            hex_of(tokens, n)?
        )?;
    }
    rs.push_str("\n// Marfil at alpha: secondary text, hairlines and membrane fills (no greys).\n");
    let marfil = hex_of(tokens, "marfil")?;
    for (step, a) in &alphas {
        writeln!(
            rs,
            "pub const MARFIL_ALPHA_{step}: Rgba = Rgba {{\n    rgb: 0x{marfil},\n    a: {a},\n}};"
        )?;
    }
    writeln!(
        rs,
        "\n/// Every opaque token as `(tokens.json key, 0xRRGGBB)`, in declaration order.\npub const ALL: [(&str, u32); {}] = [",
        names.len()
    )?;
    for n in &names {
        writeln!(rs, "    (\"{n}\", {}),", screaming(n))?;
    }
    rs.push_str("];\n");
    Ok(rs)
}

fn pair(v: &Value, what: &str) -> Result<(f64, f64)> {
    match v.as_array().map(Vec::as_slice) {
        Some([a, b]) => Ok((num(a, what)?, num(b, what)?)),
        _ => bail!("{what} is not a [x, y] pair"),
    }
}

fn generate_scale(tokens: &Value) -> Result<String> {
    let typo = object(tokens, "typography")?;
    let mut rs = String::from(HEADER_RS);
    rs.push_str("//! Typography, spacing, radius and stroke scales (logical pixels).\n\n");
    for role in ["display", "mono", "body"] {
        let t = typo
            .get(role)
            .and_then(Value::as_object)
            .ok_or_else(|| anyhow!("typography.{role} missing"))?;
        let family = t
            .get("family")
            .and_then(Value::as_str)
            .ok_or_else(|| anyhow!("typography.{role}.family missing"))?;
        let weights = t
            .get("weights")
            .and_then(Value::as_array)
            .ok_or_else(|| anyhow!("typography.{role}.weights missing"))?;
        let list: Vec<String> = weights
            .iter()
            .map(|w| num(w, "weight").map(|w| format!("{}", w as u32)))
            .collect::<Result<_>>()?;
        let up = role.to_ascii_uppercase();
        writeln!(rs, "pub const FONT_{up}: &str = \"{family}\";")?;
        writeln!(
            rs,
            "pub const FONT_{up}_WEIGHTS: [u16; {}] = [{}];",
            list.len(),
            list.join(", ")
        )?;
    }
    let fallback = typo
        .get("body")
        .and_then(|b| b.get("fallback"))
        .and_then(Value::as_str)
        .ok_or_else(|| anyhow!("typography.body.fallback missing"))?;
    writeln!(rs, "pub const FONT_BODY_FALLBACK: &str = \"{fallback}\";\n")?;

    let scale = typo
        .get("scale")
        .and_then(Value::as_object)
        .ok_or_else(|| anyhow!("typography.scale missing"))?;
    for (k, v) in scale {
        writeln!(
            rs,
            "pub const TEXT_{}: f32 = {};",
            screaming(k),
            float(num(v, k)?)
        )?;
    }
    let eb = typo
        .get("eyebrowStyle")
        .and_then(Value::as_object)
        .ok_or_else(|| anyhow!("typography.eyebrowStyle missing"))?;
    let spacing = eb
        .get("letterSpacing")
        .and_then(Value::as_str)
        .and_then(|s| s.strip_suffix("em"))
        .and_then(|s| s.parse::<f64>().ok())
        .ok_or_else(|| anyhow!("eyebrowStyle.letterSpacing is not em"))?;
    let weight = num(&eb["weight"], "eyebrowStyle.weight")?;
    writeln!(
        rs,
        "\n/// Eyebrow letter spacing in em; text is upper-case, Marfil alpha 62."
    )?;
    writeln!(
        rs,
        "pub const EYEBROW_LETTER_SPACING_EM: f32 = {};",
        float(spacing)
    )?;
    writeln!(rs, "pub const EYEBROW_WEIGHT: u16 = {};\n", weight as u32)?;

    let space = object(tokens, "space")?;
    for (k, v) in space {
        let name = format!("SPACE_{}", screaming(k));
        match v {
            Value::Array(_) => {
                let (a, b) = pair(v, k)?;
                writeln!(
                    rs,
                    "pub const {name}: [f32; 2] = [{}, {}];",
                    float(a),
                    float(b)
                )?;
            }
            _ => writeln!(rs, "pub const {name}: f32 = {};", float(num(v, k)?))?,
        }
    }
    rs.push('\n');
    for group in ["radius", "stroke"] {
        for (k, v) in object(tokens, group)? {
            writeln!(
                rs,
                "pub const {}_{}: f32 = {};",
                group.to_ascii_uppercase(),
                screaming(k),
                float(num(v, k)?)
            )?;
        }
        rs.push('\n');
    }
    Ok(rs.trim_end().to_owned() + "\n")
}

