fn kit_color(tokens: &Value, alphas: &[(String, u8)], src: &str) -> Result<String> {
    let (name, alpha) = match src.split_once('@') {
        None => (src, None),
        Some((n, a)) => {
            let alpha = if let Some(raw) = a.strip_prefix('x') {
                u8::from_str_radix(raw, 16)?
            } else {
                alphas
                    .iter()
                    .find(|(step, _)| step == a)
                    .map(|(_, v)| *v)
                    .ok_or_else(|| anyhow!("unknown Marfil alpha step `{a}`"))?
            };
            (n, Some(alpha))
        }
    };
    let hex = hex_of(tokens, name)?;
    Ok(match alpha {
        Some(a) => format!("#{hex}{a:02X}"),
        None => format!("#{hex}"),
    })
}

fn generate_kit_theme(tokens: &Value) -> Result<String> {
    let alphas = marfil_alphas(tokens)?;
    let typo = object(tokens, "typography")?;
    let family = |role: &str| {
        typo.get(role)
            .and_then(|t| t.get("family"))
            .and_then(Value::as_str)
            .ok_or_else(|| anyhow!("typography.{role}.family missing"))
    };
    let mut out = String::from(
        "{\n  \"name\": \"Pando\",\n  \"author\": \"Pando Assistant (generated by `cargo xtask tokens`)\",\n  \"themes\": [\n",
    );
    writeln!(
        out,
        "    {{\n      \"name\": \"Pando Dark\",\n      \"mode\": \"dark\",\n      \"font.family\": \"{}\",\n      \"mono_font.family\": \"{}\",\n      \"colors\": {{",
        family("body")?,
        family("mono")?
    )?;
    for (i, (key, src)) in KIT_MAP.iter().enumerate() {
        let sep = if i + 1 == KIT_MAP.len() { "" } else { "," };
        writeln!(
            out,
            "        \"{key}\": \"{}\"{sep}",
            kit_color(tokens, &alphas, src)?
        )?;
    }
    out.push_str("      }\n    }\n  ]\n}\n");
    Ok(out)
}

fn channels(hex: &str) -> [f64; 3] {
    let c = |i: usize| f64::from(u8::from_str_radix(&hex[i..i + 2], 16).unwrap_or(0));
    [c(0), c(2), c(4)]
}

fn luminance(rgb: [f64; 3]) -> f64 {
    let lin = |v: f64| {
        let v = v / 255.0;
        if v <= 0.03928 {
            v / 12.92
        } else {
            ((v + 0.055) / 1.055).powf(2.4)
        }
    };
    0.2126 * lin(rgb[0]) + 0.7152 * lin(rgb[1]) + 0.0722 * lin(rgb[2])
}

pub fn ratio(a: [f64; 3], b: [f64; 3]) -> f64 {
    let (la, lb) = (luminance(a), luminance(b));
    (la.max(lb) + 0.05) / (la.min(lb) + 0.05)
}

/// `fg` over `bg` with alpha 0-1.
fn composite(fg: [f64; 3], alpha: f64, bg: [f64; 3]) -> [f64; 3] {
    [0, 1, 2].map(|i| fg[i] * alpha + bg[i] * (1.0 - alpha))
}

/// Pairs `(foreground, alpha step, background, minimum ratio)`: text must reach 4.5:1 (WCAG AA).
/// Álamo oscuro is "never text" and is not listed.
const TEXT_PAIRS: &[(&str, Option<&str>, &str, f64)] = &[
    ("marfil", None, "bosque", 4.5),
    ("marfil", None, "bosqueDeep", 4.5),
    ("marfil", Some("62"), "bosque", 4.5),
    ("marfil", Some("62"), "bosqueDeep", 4.5),
    ("alamo", None, "bosque", 4.5),
    ("alamo", None, "bosqueDeep", 4.5),
    ("claudeBlue", None, "bosque", 4.5),
    // Error nucleus and badge are graphics, not text: WCAG 1.4.11 asks 3:1.
    ("bermellon", None, "bosque", 3.0),
    ("bosque", None, "alamo", 4.5),
    ("alamoText", None, "marfil", 4.5),
];

/// Contrast ratio of each pair with its required minimum.
pub fn contrast_rows(tokens: &Value) -> Result<Vec<(String, f64, f64)>> {
    let alphas = marfil_alphas(tokens)?;
    let mut rows = Vec::new();
    for (fg, step, bg, min) in TEXT_PAIRS {
        let bg_rgb = channels(&hex_of(tokens, bg)?);
        let mut fg_rgb = channels(&hex_of(tokens, fg)?);
        let mut label = format!("{fg} on {bg}");
        if let Some(step) = step {
            let a = alphas
                .iter()
                .find(|(s, _)| s == step)
                .map(|(_, a)| f64::from(*a) / 255.0)
                .ok_or_else(|| anyhow!("unknown alpha step {step}"))?;
            fg_rgb = composite(fg_rgb, a, bg_rgb);
            label = format!("{fg}@{step} on {bg}");
        }
        rows.push((label, ratio(fg_rgb, bg_rgb), *min));
    }
    Ok(rows)
}

fn contrast(tokens: &Value) -> Result<bool> {
    let mut ok = true;
    for (label, r, min) in contrast_rows(tokens)? {
        let pass = r >= min;
        ok &= pass;
        println!(
            "{} {label:32} {r:5.1}:1 (min {min})",
            if pass { "OK " } else { "LOW" }
        );
    }
    Ok(ok)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn tokens() -> Value {
        read_tokens(&repo_root().expect("root")).expect("tokens")
    }

    #[test]
    fn snake_case() {
        assert_eq!(snake("bosqueDeep"), "bosque_deep");
        assert_eq!(snake("cellSpringKNewborn"), "cell_spring_k_newborn");
        assert_eq!(screaming("alamoText"), "ALAMO_TEXT");
    }

    #[test]
    fn alpha_ramp_is_rounded_to_u8() {
        let a = marfil_alphas(&tokens()).expect("ramp");
        assert_eq!(a[0], ("62".to_owned(), 158));
        assert_eq!(a.len(), 5);
    }

    #[test]
    fn generated_files_are_up_to_date() {
        let root = repo_root().expect("root");
        assert!(
            check(&root, &tokens()).expect("check"),
            "run `cargo xtask tokens`"
        );
    }

    #[test]
    fn brand_text_pairs_reach_aa() {
        for (label, r, min) in contrast_rows(&tokens()).expect("rows") {
            assert!(r >= min, "{label} is {r:.2}:1 (< {min})");
        }
    }

    #[test]
    fn generated_rust_is_rustfmt_stable() {
        let root = repo_root().expect("root");
        let status = std::process::Command::new("rustfmt")
            .args(["--edition", "2024", "--check"])
            .args(["--config-path"])
            .arg(root.join("rustfmt.toml"))
            .arg(root.join(super::PALETTE))
            .arg(root.join(super::SCALE))
            .status()
            .expect("run rustfmt");
        assert!(status.success(), "generated Rust is not rustfmt-clean");
    }

    #[test]
    fn palette_is_deterministic() {
        let t = tokens();
        assert_eq!(
            generate_palette(&t).expect("a"),
            generate_palette(&t).expect("b")
        );
    }
}
